// murmur3: MurmurHash3 (x86, 32-bit, seed 0) of 8 MiB of generated bytes.
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static uint32_t rotl(uint32_t x, int r) { return x << r | x >> (32 - r); }

int main(void) {
    const int64_t n = 1 << 23;
    uint8_t *data = malloc(n);
    for (int64_t i = 0; i < n; i++) data[i] = (uint8_t)((i * 2654435761LL >> 13) & 255);
    uint32_t h = 0;
    for (int64_t i = 0; i < n; i += 4) {
        uint32_t k;
        memcpy(&k, data + i, 4); // little-endian, as the hash reads its blocks
        k = rotl(k * 0xcc9e2d51u, 15) * 0x1b873593u;
        h = rotl(h ^ k, 13) * 5 + 0xe6546b64u;
    }
    h ^= (uint32_t)n;
    h = (h ^ h >> 16) * 0x85ebca6bu;
    h = (h ^ h >> 13) * 0xc2b2ae35u;
    h ^= h >> 16;
    printf("%u\n", h);
    free(data);
    return 0;
}
